set -u; D=~/.cache/g250-dav; rm -rf "$D"; mkdir -p "$D/cfg"; cd "$D"
echo '' | base64 -d | gunzip > responder.py
python3 responder.py "$D/capture.jsonl" "$D/port" > "$D/responder.log" 2>&1 &
RP=$!
for i in $(seq 1 50); do [ -s "$D/port" ] && break; sleep 0.1; done
PORT=$(cat "$D/port"); U="http://127.0.0.1:$PORT/repo"
SVN="svn --non-interactive --no-auth-cache --config-dir $D/cfg --config-option servers:global:http-timeout=10"
run() { echo "## $*" | sed "s#$D#D#g"; "$@" > "$D/out.txt" 2>&1; echo "exit $?"; tail -2 "$D/out.txt" | sed "s#$D#D#g"; }
run $SVN log -v --limit 2 -r 5:1 "$U/trunk"
run $SVN log -r '{2026-01-01}' "$U/trunk"
run $SVN ls -v "$U/trunk"
run $SVN info "$U/trunk/f.txt"
run $SVN cat -r 2 "$U/trunk/f.txt@5"
run $SVN log -r 2:1 "$U/trunk@5"
run $SVN mergeinfo "$U/trunk" "$U/branches/b"
run $SVN propget svn:ignore --show-inherited-props "$U/trunk/d"
run $SVN checkout "$U/trunk" "$D/wc"
run svnrdump dump --non-interactive --no-auth-cache --config-dir "$D/cfg" -r 1:1 "$U"
run $SVN mkdir -m "add a directory" "$U/trunk/newdir"
kill $RP; wait $RP 2>/dev/null
echo "== RESPONDER LOG"; tail -5 "$D/responder.log"
echo "== CAPTURE"; cat "$D/capture.jsonl"
cd ~ && rm -rf "$D"
